import{_ as a,o as t,c as r,ag as n}from"./chunks/framework.DCKC-kU_.js";const m=JSON.parse('{"title":"Form Proposal: StatefulEntity","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/stateful-entity.md","filePath":"proposals/stateful-entity.md"}'),i={name:"proposals/stateful-entity.md"};function o(s,e,d,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="form-proposal-statefulentity" tabindex="-1">Form Proposal: StatefulEntity <a class="header-anchor" href="#form-proposal-statefulentity" aria-label="Permalink to &quot;Form Proposal: StatefulEntity&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>Takosumi Cloud runs a namespace of addressable durable entities from immutable application code. The candidate Form describes namespace identity, digest-bound code, a generic entrypoint, runtime and persistence capability requirements, non-secret configuration, connections, and an entity invocation Interface. Runtime implementation, storage engine, migrations, placement, replication, credentials, routing, and price remain host-owned.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>Addressable entity namespaces can be implemented by Durable Objects-like isolates, an actor runtime, or a transactional database-backed host. The Form uses a generic entrypoint and open persistence requirement; class deployment, migration tags, shard placement, replication, routing, alarms, and account bindings are excluded as substrate operation.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Namespace or storage-model changes need explicit migration and may not permit replacement. Delete can destroy durable entity state and requires evacuation or retention policy. Entity data, storage credentials, and invocation secrets never enter portable state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Resource/Link/Action, TOSCA stateful components, Kubernetes StatefulSet and operator patterns, and Terraform durable-object/actor resources are applicable; CIMI does not model addressable entity namespaces directly. The gap is a namespace-level contract without standardizing the host actor runtime or storage engine.</p>',10)])])}const b=a(i,[["render",o]]);export{m as __pageData,b as default};
